export class Basket {
    constructor() {
        this.items = [];
        this.totalPrice = 0;
    }
    addItem(product) {
        this.items.push(product);
        this.updateTotalPrice();
    }
    removeItem(productId) {
        this.items = this.items.filter(item => item.id !== productId);
        this.updateTotalPrice();
    }
    clear() {
        this.items = [];
        this.totalPrice = 0;
    }
    updateTotalPrice() {
        this.totalPrice = this.items.reduce((sum, item) => sum + item.price, 0);
    }
}
