import { SETTINGS } from "../../utils/constants";
import { cloneTemplate, ensureElement } from "../../utils/utils";
export class ProductCardView {
    render(product) {
        const cardTemplate = ensureElement(SETTINGS.cardTemplate);
        const card = cloneTemplate(cardTemplate);
        const titleElement = ensureElement(SETTINGS.productSettings.title, card);
        const categoryElement = ensureElement(SETTINGS.productSettings.category, card);
        const imageElement = ensureElement(SETTINGS.productSettings.image, card);
        const priceElement = ensureElement(SETTINGS.productSettings.price, card);
        titleElement.textContent = product.title;
        categoryElement.textContent = product.category;
        imageElement.src = product.image;
        if (product.price == null) {
            priceElement.textContent = `бесценно`;
        }
        else {
            priceElement.textContent = `${product.price} синапсов`;
        }
        switch (product.category) {
            case 'софт-скил':
                categoryElement.classList.add('card__category_soft');
                break;
            case 'дополнительное':
                categoryElement.classList.add('card__category_additional');
                break;
            case 'кнопка':
                categoryElement.classList.add('card__category_button');
                break;
            case 'хард-скил':
                categoryElement.classList.add('card__category_hard');
                break;
            default:
                categoryElement.classList.add('card__category_other');
        }
        return card;
    }
}
